CREATE VIEW public.v_duplicate_review_queue AS
 SELECT duplicate_relation_id,
    complaint_id,
    similar_complaint_id,
    master_complaint_id,
    text_similarity,
    distance_meters,
    time_difference_hours,
    duplicate_score,
    decision,
    decision_source,
    review_required,
    review_decision,
    reviewed_by,
    reviewed_at,
    review_comment,
    created_at
   FROM public.duplicate_relation dr
  WHERE ((review_required = true) AND (reviewed_at IS NULL));


